// warehouse-map · кейсы wm-04, wm-05, wm-11 (.qa/tests/warehouse-map/) — режим «עריכת המפה» БЕЗ сохранения.
// Карта — реальная раскладка клиента: ничего не меняем, «שמירת מפה» НЕ нажимаем, выходим «סיום עריכה».
// Сетевой guard абортирует любую запись в Supabase и валит тест, если она была.
import { test, expect, Page } from '@playwright/test';
import { auth, side, openMap, guardWrites } from './_helpers';

test.use({ storageState: auth('admin') });

const UNIFORM = { h: 44, bg: 'rgb(255, 255, 255)', border: '1px solid rgb(231, 233, 238)', radius: '8px', font: '14px/500' };

async function btnStyle(page: Page, name: string) {
  return page
    .getByRole('button', { name, exact: true })
    .first()
    .evaluate((e) => {
      const s = getComputedStyle(e);
      return { h: Math.round(e.getBoundingClientRect().height), bg: s.backgroundColor, border: s.border, radius: s.borderRadius, font: `${s.fontSize}/${s.fontWeight}`, color: s.color };
    });
}

async function enterEdit(page: Page) {
  await page.getByRole('button', { name: 'עריכת המפה' }).click();
  await expect(page.getByRole('button', { name: 'סיום עריכה' })).toBeVisible();
}
async function exitEdit(page: Page) {
  await page.getByRole('button', { name: 'סיום עריכה' }).click();
  await expect(page.getByRole('button', { name: 'עריכת המפה' })).toBeVisible();
  await expect(page.getByRole('dialog')).toHaveCount(0);
}

test.describe('warehouse-map — עריכת מפה (צפייה בלבד, בלי שמירה)', () => {
  let violations: string[] = [];
  test.beforeEach(async ({ page }) => {
    violations = await guardWrites(page);
  });
  test.afterEach(() => {
    expect(violations, 'режим редактирования не должен ничего записывать').toEqual([]);
  });

  test('כפתורי פעולות אחידים; אין «הוספת פריט» בראש העמוד בעריכה #6a859245 @desktop @prod-safe', async ({ page }) => {
    await openMap(page);
    for (const name of ['החזרות', 'הוספת פריט', 'עריכת המפה']) {
      const st = await btnStyle(page, name);
      expect(st, name).toMatchObject(UNIFORM);
    }
    await enterEdit(page);
    for (const name of ['שמירת מפה', 'סיום עריכה', 'מחיקת הקומה']) {
      const st = await btnStyle(page, name);
      expect(st, name).toMatchObject(UNIFORM);
    }
    expect((await btnStyle(page, 'מחיקת הקומה')).color).toBe('rgb(168, 57, 52)');
    await expect(page.getByRole('button', { name: 'הוספת פריט', exact: true })).toHaveCount(0);
    await expect(page.getByRole('button', { name: 'כיווץ הוספת פריט' })).toBeVisible();
    await exitEdit(page);
  });

  test('פלטת סוגי אחסון ומונחים: ארון → מדפים, משטח → ארגזים #6a730a70 #6a85943e #6a5cb979 @desktop @prod-safe', async ({ page }) => {
    await openMap(page, 'קומה 1');
    // выбираем ארגז на משטח в просмотре — в редакторе откроются его свойства с переходом к «המשטח»
    const pallet = side(page).getByRole('button', { name: /^משטח .* ארגזים? / }).first();
    test.skip(!(await pallet.count()), 'на «קומה 1» нет משטח с ארגזים');
    await pallet.click();
    await side(page).getByRole('listitem').first().getByRole('button').first().click();
    await expect(side(page).getByRole('heading', { name: 'תכולת הארגז' })).toBeVisible();

    await enterEdit(page);
    for (const t of ['אזור', 'משטח', 'ארון', 'ארגז', 'אזור ארגזים', 'עמודה', 'קיר', 'דלת']) {
      await expect(page.getByRole('button', { name: t, exact: true })).toBeVisible();
    }
    await expect(page.getByRole('button', { name: 'משטח', exact: true })).toHaveAttribute('title', /אפשר לחלק אותו לארגזים/);

    const s = side(page);
    await expect(s.getByText('מאפייני ארגז')).toBeVisible();
    await s.getByRole('button', { name: /^המשטח/ }).click();
    await expect(s.getByText('מאפייני משטח')).toBeVisible();
    await expect(s.getByText('ארגזים לרוחב')).toBeVisible();
    await expect(s.getByText('ארגזים לעומק')).toBeVisible();
    await expect(s.getByRole('button', { name: 'הוספת ארגז' })).toBeVisible();
    await expect(s.getByRole('button', { name: 'סידור הארגזים מחדש במשטח' })).toBeVisible();
    await expect(s.getByText('ארגזים על המשטח')).toHaveCount(0);
    await expect(s.getByText(/מדף/)).toHaveCount(0);

    // ארון: клик по подписи на холсте (без перетаскивания) — только чтение свойств
    const cab = page.getByRole('application', { name: 'קנבס המחסן' }).getByText('ארון A', { exact: true }).first();
    if (await cab.count()) {
      await cab.click({ force: true });
      await expect(s.getByText('מאפייני ארון')).toBeVisible();
      await expect(s.getByText('מדפים לרוחב')).toBeVisible();
      await expect(s.getByRole('button', { name: 'הוספת מדף' })).toBeVisible();
      await expect(s.getByRole('button', { name: 'סידור המדפים מחדש בארון' })).toBeVisible();
    }
    await exitEdit(page);
  });

  test('כלי עריכה: נקודת התחלה לליקוט, ביטול/ביצוע מחדש, הצמדה לרשת #6a5cb979 @desktop @prod-safe', async ({ page }) => {
    await openMap(page);
    await enterEdit(page);
    await expect(page.getByRole('button', { name: /^נקודת התחלה — ממנה נגזר סדר הארונות ברשימת הליקוט/ })).toBeVisible();
    await expect(page.getByRole('button', { name: /^הצמדה לרשת/ })).toBeVisible();
    for (const b of ['ביטול פעולה', 'ביצוע מחדש', 'בחר', 'זוז', 'מחק']) {
      await expect(page.getByRole('button', { name: b, exact: true })).toBeVisible();
    }
    await exitEdit(page);
  });
});
